scripts.script:
_G.InfFish = true -- Change to false if you want to stop

while _G.InfFish == true do
local args = {
    [1] = {
        [5002102] = 6
    }
}

game:GetService("ReplicatedStorage").ServerMsg.CatchFish:FireServer(unpack(args))
wait(0.1)
end

local Events = {
    FireServer = true
}

local gameMeta = getrawmetatable(game)
local psuedoEnv = {
    ["__index"] = gameMeta.__index,
    ["__namecall"] = gameMeta.__namecall;
}
setreadonly(gameMeta, false)
gameMeta.__index, gameMeta.__namecall = newcclosure(function(self, index, ...)
    if Events[index] then
        if "KickPlayer" == self.Name and not checkcaller() then return nil end
    end
    return psuedoEnv.__index(self, index, ...)
end)
setreadonly(gameMeta, true)

